<script>
document.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.passwordToggle),show=input.type==='password';input.type=show?'text':'password';button.innerHTML=`<i class="fa-regular fa-eye${show?'-slash':''}"></i>`;button.setAttribute('aria-label',show?'ซ่อนรหัสผ่าน':'แสดงรหัสผ่าน')}));
const password=document.getElementById('password'),confirmPassword=document.getElementById('passwordConfirm'),meter=document.getElementById('passwordMeter'),strength=document.getElementById('passwordStrength'),matchHint=document.getElementById('matchHint');
function updatePasswordState(){const value=password.value;let score=0;if(value.length>=8)score++;if(/[A-Za-z]/.test(value)&&/\d/.test(value))score++;if(/[A-Z]/.test(value)&&/[a-z]/.test(value))score++;if(/[^A-Za-z0-9]/.test(value))score++;const labels=['ยังไม่ปลอดภัย','พอใช้','ปานกลาง','ดี','แข็งแรง'];const colors=['#b83b32','#d96d2f','#c28a25','#4d8067','#247044'];meter.style.width=(score*25)+'%';meter.style.background=colors[score];strength.textContent=value?labels[score]:'ต้องมีตัวอักษรและตัวเลข';strength.style.color=value?colors[score]:'';const mismatch=confirmPassword.value!==''&&value!==confirmPassword.value;confirmPassword.setCustomValidity(mismatch?'รหัสผ่านไม่ตรงกัน':'');matchHint.textContent=confirmPassword.value?(mismatch?'รหัสผ่านยังไม่ตรงกัน':'รหัสผ่านตรงกันแล้ว'):'';matchHint.style.color=mismatch?'var(--danger)':'#247044'}password.addEventListener('input',updatePasswordState);confirmPassword.addEventListener('input',updatePasswordState);
function showAuthError(message,field){const box=document.getElementById('authError');box.querySelector('span').textContent=message;box.classList.add('show');document.querySelectorAll('.auth-field').forEach(el=>el.classList.remove('invalid'));if(field){const input=document.querySelector(`[name="${field}"]`);if(input){input.closest('.auth-field')?.classList.add('invalid');input.focus()}}}
document.getElementById('registerForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=document.getElementById('registerBtn');document.getElementById('authError').classList.remove('show');updatePasswordState();if(!form.reportValidity())return;button.disabled=true;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> กำลังสร้างบัญชี';try{const response=await fetch(`${BASE_URL}api/auth.php`,{method:'POST',body:new FormData(form)});const result=await response.json();if(!response.ok||result.status!=='success')throw Object.assign(new Error(result.message||'ไม่สามารถสมัครสมาชิกได้'),{field:result.data?.field});showToast(result.message,'success');setTimeout(()=>location.href=result.data.redirect,350)}catch(error){showAuthError(error.message,error.field);button.disabled=false;button.innerHTML='<span>สร้างบัญชีสมาชิก</span><i class="fa-solid fa-user-plus"></i>'}});
</script>
